def comb_sort(nums):
    n = len(nums)
    gap = n
    sorted_list = nums.copy()  # Create a copy to avoid modifying the original list
    shrink_factor = 1.3

    while gap > 1:
        gap = max(1, int(gap / shrink_factor))
        for i in range(n - gap):
            if sorted_list[i] > sorted_list[i + gap]:
                sorted_list[i], sorted_list[i + gap] = sorted_list[i + gap], sorted_list[i]
    return sorted_list
```

