def max_run_uppercase(test_str):
    max_run = 0
    current_run = 0

    for i in range(len(test_str)):
        if test_str[i].isupper():
            current_run += 1
        else:
            if current_run > max_run:
                max_run = current_run
            current_run = 0
        # Check one last time in case the string ends with uppercase
        if i == len(test_str) - 1 and current_run > max_run:
            max_run = current_run

    return max_run
```

