def max_run_uppercase(test_str):
    max_run = 0
    current_run = 0

    for char in test_str:
        if char.isupper():
            current_run += 1
        else:
            max_run = max(max_run, current_run)
            current_run = 0
    max_run = max(max_run, current_run)  # Check one last time in case all chars were uppercase
    return max_run
```
